const edges=[['eye','relayA',9],['eye','relayB',6],['eye','relayC',4],['relayA','hub',9],['relayA','dance',4],['relayB','hub',3],['relayB','sidecar',6],['relayC','cross',4],['hub','gate',9],['hub','split',7],['sidecar','loop',6],['sidecar','cross',3],['sidecar','orient',4],['cross','ghost',4],['gate','escape',9],['ghost','escape',4],['split','backup',6],['split','dance',8],['split','loop',4],['loop','backup',5],['loop','orient',7],['backup','escape',7]];
let state;const $=s=>document.querySelector(s),board=$('#board'),nodeBy=id=>nodes.find(n=>n.id===id);
function reset(){state={started:false,turn:0,lesions:3,jams:2,tool:'lesion',selected:null,disabled:new Set(),jammed:new Set(),contain:0,protected:100,history:[],lastPaths:[]};render();$('#startOverlay').classList.remove('hidden');$('#routeCards').classList.add('hidden');$('#advanceBtn').disabled=true;$('#quip').textContent='“The fly has no idea you’re here. Mostly because this is a graph.”';}
function el(tag,attrs={}){const e=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e}function pathData(a,b){const x1=a.x+24,x2=b.x-24,m=(x1+x2)/2;return `M${x1},${a.y} C${m},${a.y} ${m},${b.y} ${x2},${b.y}`}function edgeKey(a,b){return `${a}-${b}`}
function routeClass(a,b){if(state.disabled.has(a)||state.disabled.has(b))return 'edge dead';const active=new Set(state.lastPaths.flatMap(p=>p.edges.map(e=>edgeKey(...e))));if(active.has(edgeKey(a,b)))return state.turn>1?'edge reroute':'edge active';return 'edge'}
function render(){board.innerHTML='';edges.forEach(([a,b])=>board.append(el('path',{d:pathData(nodeBy(a),nodeBy(b)),class:routeClass(a,b),'data-edge':edgeKey(a,b)})));nodes.forEach(n=>{const g=el('g',{class:`node ${n.kind||''} ${state.disabled.has(n.id)?'disabled':''} ${state.jammed.has(n.id)?'jammed':''} ${state.selected===n.id?'selected':''}`,transform:`translate(${n.x} ${n.y})`,tabindex:n.locked?'-1':'0',role:'button','aria-label':n.name});g.append(el('circle',{r:n.kind?27:22}));if(n.kind==='source')g.append(el('circle',{r:34,class:'pulse-ring'}));const t=el('text',{'text-anchor':'middle',y:42});t.textContent=n.name;g.append(t);const m=el('text',{'text-anchor':'middle',y:56,class:'mini'});m.textContent=n.role;g.append(m);if(!n.locked){g.addEventListener('click',()=>selectNode(n.id));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')selectNode(n.id)})}board.append(g)});updateUI()}
function updateUI(){$('#turnTop').textContent=`${state.turn}/6`;$('#containTop').textContent=`${state.contain}%`;$('#lesionsLeft').textContent=state.lesions;$('#jamsLeft').textContent=state.jams;document.querySelectorAll('.tool').forEach(x=>x.classList.toggle('selected',x.dataset.tool===state.tool));}
function selectNode(id){if(!state.started)return;state.selected=id;const n=nodeBy(id);$('#emptyIntel').classList.add('hidden');$('#nodeIntel').classList.remove('hidden');$('#nodeRole').textContent=n.role;$('#nodeName').textContent=n.name;$('#nodeId').textContent=`TYPE GROUP // ${n.count} NEURONS`;$('#strengthBar').style.width=n.s+'%';$('#strengthVal').textContent=n.s;$('#loadBar').style.width=n.l+'%';$('#loadVal').textContent=n.l;$('#forecastText').textContent=n.f;const btn=$('#actionBtn'),used=state.disabled.has(id);btn.textContent=used?'ALREADY DISABLED':`${state.tool==='lesion'?'CUT':'JAM'} NODE`;btn.disabled=used||(state.tool==='lesion'?state.lesions<1:state.jams<1);render()}
function intervene(){const id=state.selected;if(!id)return;if(state.tool==='lesion'){state.disabled.add(id);state.lesions--;quip(id==='hub'?'“Grand Central is dark. Three smaller stations would like your attention.”':id==='split'?'“Fork 9 is gone. So is a regrettable amount of innocent traffic.”':id==='gate'?'“Primary gate down. The backup committee has convened.”':'“Node removed. The network is filing an appeal.”')}else{state.jammed.add(id);state.jams--;quip('“Temporary jam deployed. Neural hold music begins now.”')}state.selected=null;$('#nodeIntel').classList.add('hidden');$('#emptyIntel').classList.remove('hidden');$('#advanceBtn').disabled=false;$('#systemState').textContent='INTERVENTION ARMED';render();toast('Intervention locked. Advance the signal.')}
function allPaths(target,blocked=new Set()){const adj={};edges.forEach(([a,b,w])=>(adj[a]??=[]).push({to:b,w}));const out=[];function walk(id,seen,ns,es,weights){if(id===target){out.push({nodes:ns,edges:es,capacity:Math.min(...weights)});return}for(const e of adj[id]||[]){if(blocked.has(e.to)||seen.has(e.to))continue;walk(e.to,new Set([...seen,e.to]),[...ns,e.to],[...es,[id,e.to]],[...weights,e.w])}}if(!blocked.has('eye'))walk('eye',new Set(['eye']),['eye'],[],[]);return out.sort((a,b)=>b.capacity-a.capacity)}
function targetPaths(){const blocked=new Set([...state.disabled,...state.jammed]),paths=allPaths('escape',blocked),chosen=[];for(const p of paths){const sig=p.edges.map(e=>edgeKey(...e));const duplicate=chosen.some(c=>c.edges.filter(e=>sig.includes(edgeKey(...e))).length/Math.max(1,c.edges.length)>.7);if(!duplicate)chosen.push(p);if(chosen.length===4)break}return chosen}function totalCapacity(paths){return paths.reduce((s,p)=>s+p.capacity,0)}
function protectedScore(){const blocked=new Set(state.disabled),dance=totalCapacity(allPaths('dance',blocked).slice(0,2)),orient=totalCapacity(allPaths('orient',blocked).slice(0,2));return Math.round(100*Math.min(1,(dance/12+orient/11)/2))}
function showRoutes(paths){const box=$('#routeCards');if(!paths.length){box.classList.add('hidden');return}const names=['PRIMARY','SHARED BYPASS','SHADOW ROUTE','GHOST ROUTE'];box.innerHTML=paths.map((p,i)=>`<article class="route-card" data-route="${i}"><b>${p.capacity}</b><small>ROUTE ${String.fromCharCode(65+i)}</small><strong>${names[i]||'REROUTE'}</strong><p>${p.nodes.map(id=>nodeBy(id).name).join(' → ')}</p></article>`).join('');box.classList.remove('hidden');box.querySelectorAll('.route-card').forEach(card=>{card.onmouseenter=()=>highlightRoute(paths[+card.dataset.route]);card.onmouseleave=()=>render()})}
function highlightRoute(path){const keep=new Set(path.edges.map(e=>edgeKey(...e)));board.querySelectorAll('.edge').forEach(e=>{e.style.opacity=keep.has(e.dataset.edge)?'1':'.12';e.style.strokeWidth=keep.has(e.dataset.edge)?'5':'1'})}
function advance(){if(state.turn>=6)return;state.turn++;const paths=targetPaths();state.lastPaths=paths;state.history.push(paths);state.contain=Math.round(100*Math.max(0,1-totalCapacity(paths)/24));state.protected=protectedScore();state.jammed.clear();$('#advanceBtn').disabled=true;$('#systemState').textContent=paths.length>1?`${paths.length} ROUTES ACTIVE`:paths.length?'ONE ROUTE ACTIVE':'SIGNAL CONTAINED';render();showRoutes(paths);animatePaths(paths);if(!paths.length)quip('“Full containment. The target has been stood up by every signal.”');else if(paths.length===4)quip('“Four routes. The tiny quiet one is absolutely plotting something.”');else if(state.turn>1)quip(`“It rerouted through ${paths.map(p=>nodeBy(p.nodes.at(-2)).name).join(' and ')}. Rude.”`);else quip('“Contact. Multiple paths are carrying signal. Try looking tactical.”');if(state.turn===6||(!paths.length&&state.turn>=2))setTimeout(finish,1200)}
function animatePaths(paths){const colors=['var(--cyan)','var(--amber)','var(--violet)','var(--acid)'];paths.forEach((path,p)=>path.edges.forEach(([a,b],i)=>setTimeout(()=>{const B=nodeBy(b),c=el('text',{x:B.x,y:B.y+7,class:'courier','text-anchor':'middle',style:`filter:drop-shadow(0 0 8px ${colors[p]})`});c.textContent='🪰';board.append(c);setTimeout(()=>c.remove(),720)},i*260+p*110)))}
function finish(){const containment=state.contain,precision=state.protected,unused=state.lesions+state.jams,score=Math.max(0,Math.min(100,Math.round(containment*.68+precision*.32+unused*2)));let rank='D',title='TOTAL NEURAL CHAOS',copy='The target is confused. Unfortunately, so is everything else.';if(score>=88){rank='S';title='SURGICAL SABOTEUR';copy='You sealed every target route while the protected outputs kept humming.'}else if(score>=72){rank='A';title='CLEAN GETAWAY';copy='A precise hit with only minor neural awkwardness.'}else if(score>=52){rank='B';title='MESSY, BUT EFFECTIVE';copy='Strong containment, but several innocent pathways would like a word.'}$('#rank').textContent=rank;$('#resultTitle').textContent=title;$('#resultCopy').textContent=copy;$('#finalContain').textContent=containment+'%';$('#finalPrecision').textContent=precision+'%';$('#finalStyle').textContent='+'+(unused*3);$('#youScore').textContent=score;$('#youBar').style.setProperty('--w',score+'%');const broad=state.disabled.has('hub')||state.disabled.has('split');$('#insight').innerHTML=broad?'<strong>What happened:</strong> You attacked shared infrastructure. Strong suppression, but protected routes paid the bill. Try combining the primary gate with convergence points on the two backups.':'<strong>What happened:</strong> You targeted route-specific gates rather than the biggest hubs—the structural equivalent of stealing the keys instead of demolishing the building.';$('#resultDialog').showModal()}
function start(){state.started=true;$('#startOverlay').classList.add('hidden');$('#advanceBtn').disabled=false;toast('Advance once to reveal all four routes—or gamble immediately.')}function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}function quip(s){$('#quip').textContent=s}
function endCinematic(){const c=$('#cinematic');if(!c||c.classList.contains('gone'))return;c.style.transition='opacity .45s ease';c.style.opacity='0';setTimeout(()=>c.classList.add('gone'),480)}
document.querySelectorAll('.tool').forEach(b=>b.onclick=()=>{state.tool=b.dataset.tool;if(state.selected)selectNode(state.selected);updateUI()});$('#actionBtn').onclick=intervene;$('#advanceBtn').onclick=advance;$('#startBtn').onclick=start;$('#overlayStart').onclick=start;$('#resetBtn').onclick=reset;$('#replayBtn').onclick=()=>{$('#resultDialog').close();reset();start()};$('#methodBtn').onclick=()=>$('#methodDialog').showModal();$('#flyBtn').onclick=()=>$('#flyDialog').showModal();$('#skipIntro').onclick=endCinematic;setTimeout(endCinematic,10000);document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());reset();
